#!/usr/bin/env bash
# ============================================================
# 10-auth-profile-redesign.sh   (run once, then deploy web)
#
# Redesigns the auth surfaces to the approved mockup on Nexum's warm gold-on-
# dark brand, and adds idle sign-out. All working logic preserved verbatim;
# only JSX/styling changes.
#   A) app/(auth)/signin/page.tsx      elevated sign-in card + idle notice
#   B) components/auth/AccountMenu.tsx  avatar profile chip + richer dropdown
#   C) hooks/useIdleSignOut.ts (NEW)    30-min inactivity -> full sign-out
#   D) components/auth/AuthGuard.tsx    mounts the idle hook app-wide
#
# useAuth is intentionally NOT modified (useCircleTx already imports useAuth;
# reversing it would be circular). The idle hook clears the signing session
# itself; AccountMenu clears it on manual sign-out.
# ============================================================
set -euo pipefail

if [ -d "nexum-web" ]; then WEB="nexum-web"
elif [ -d "$HOME/AfriFX/nexum-web" ]; then WEB="$HOME/AfriFX/nexum-web"
else echo "ERROR: run from repo root or ~/AfriFX"; exit 1; fi

SIGNIN="$WEB/app/(auth)/signin/page.tsx"
MENU="$WEB/components/auth/AccountMenu.tsx"
GUARD="$WEB/components/auth/AuthGuard.tsx"
HOOK="$WEB/hooks/useIdleSignOut.ts"
for f in "$SIGNIN" "$MENU" "$GUARD"; do [ -f "$f" ] || { echo "ERROR: $f not found"; exit 1; }; done

echo "Writing redesigned sign-in page..."
base64 -d > "$SIGNIN" <<'B64_SIGNIN'

B64_SIGNIN

echo "Writing redesigned AccountMenu..."
base64 -d > "$MENU" <<'B64_MENU'

B64_MENU

echo "Creating useIdleSignOut hook..."
base64 -d > "$HOOK" <<'B64_HOOK'

B64_HOOK

echo "Mounting useIdleSignOut in AuthGuard..."
PL="$(mktemp /tmp/guard.XXXXXX.pl)"
cat > "$PL" <<'PERL'
use strict; use warnings;
local $/; my $f = shift; open my $fh,'<',$f or die $!; my $s=<$fh>; close $fh;

my $imp_old = "import { useAuth } from '\@/hooks/useAuth'";
my $imp_new = "import { useAuth } from '\@/hooks/useAuth'\nimport { useIdleSignOut } from '\@/hooks/useIdleSignOut'";
my $c = () = $s =~ /\Q$imp_old\E/g; die "guard import: $c\n" unless $c==1;
$s =~ s/\Q$imp_old\E/$imp_new/;

my $call_old = "  const { account, loading } = useAuth()\n  const router   = useRouter()";
my $call_new = "  const { account, loading } = useAuth()\n  useIdleSignOut()\n  const router   = useRouter()";
$c = () = $s =~ /\Q$call_old\E/g; die "guard call: $c\n" unless $c==1;
$s =~ s/\Q$call_old\E/$call_new/;

open my $out,'>',$f or die $!; print $out $s; close $out;
print "AuthGuard.tsx: idle hook mounted.\n";
PERL
perl "$PL" "$GUARD"; rm -f "$PL"

echo
echo "Verify:"
grep -c "GoogleGlyph" "$SIGNIN"      | sed 's/^/  signin GoogleGlyph: /'
grep -c "secured by Circle" "$SIGNIN"| sed 's/^/  signin trust line: /'
grep -c "clearSigningSession" "$MENU"| sed 's/^/  menu clears signing: /'
grep -n "useIdleSignOut" "$GUARD"    | sed 's/^/  guard: /'
[ -f "$HOOK" ] && echo "  hook created: yes"
echo
echo "Deploy (web only):"
echo "  cd $WEB && rm -rf .next && npx tsc --noEmit && npm run build"
echo "  git add -A && git commit -m 'feat(auth): redesign signin + profile button, idle sign-out' && git push"
